insert into inf.setting_definitions (key, grp, label, description, json_schema, default_value, edit_permission, needs_confirmation) values
  ('organisation.profile', 'organisation', 'Legal entity', 'Name, address and tax identifiers printed on contracts, statements and payout advice.', '{"type":"object","properties":{"legal_name":{"type":"string","minLength":2,"maxLength":200},"trade_name":{"type":"string","maxLength":120},"address":{"type":"string","maxLength":500},"state_code":{"type":"string","pattern":"^(\\d{2})?$"},"gstin":{"type":"string","pattern":"^(\\d{2}[A-Z]{5}\\d{4}[A-Z][1-9A-Z]Z[0-9A-Z])?$"},"pan":{"type":"string","pattern":"^([A-Z]{5}\\d{4}[A-Z])?$"},"support_email":{"type":"string","maxLength":200}},"required":["legal_name","trade_name","address","state_code","gstin","pan","support_email"],"additionalProperties":false}'::jsonb, '{"legal_name":"Eduwit Learning Services","trade_name":"Eduwit","address":"Ghaziabad, Uttar Pradesh","state_code":"09","gstin":"","pan":"","support_email":"creators@eduwit.in"}'::jsonb, 'settings.write', null),
  ('attribution.rules', 'attribution', 'Attribution rules', 'Window, model, duplicate and self-referral rules (spec 9.2).', '{"type":"object","properties":{"window_days":{"type":"integer","minimum":1,"maximum":365},"model":{"type":"string","enum":["first_touch","last_touch","first_touch_with_assisted"]},"duplicate_grace_minutes":{"type":"integer","minimum":0,"maximum":1440},"reenquiry_credit_after_days":{"anyOf":[{"type":"integer","minimum":1,"maximum":3650},{"type":"null"}]},"self_referral_match_phone":{"type":"boolean"},"self_referral_match_email":{"type":"boolean"},"self_referral_match_family":{"type":"boolean"}},"required":["window_days","model","duplicate_grace_minutes","reenquiry_credit_after_days","self_referral_match_phone","self_referral_match_email","self_referral_match_family"],"additionalProperties":false}'::jsonb, '{"window_days":90,"model":"first_touch_with_assisted","duplicate_grace_minutes":10,"reenquiry_credit_after_days":null,"self_referral_match_phone":true,"self_referral_match_email":true,"self_referral_match_family":true}'::jsonb, 'settings.write', null),
  ('attribution.fraud', 'attribution', 'Fraud signals', 'Thresholds that send leads to admin review. Signals never reject a lead automatically.', '{"type":"object","properties":{"velocity_leads_per_hour":{"type":"integer","minimum":1,"maximum":10000},"same_device_max_leads":{"type":"integer","minimum":1,"maximum":1000},"no_witty_reply_hours":{"type":"integer","minimum":1,"maximum":720},"off_hours_start":{"type":"string","pattern":"^([01]\\d|2[0-3]):[0-5]\\d$"},"off_hours_end":{"type":"string","pattern":"^([01]\\d|2[0-3]):[0-5]\\d$"},"off_hours_burst":{"type":"integer","minimum":1,"maximum":1000},"junk_rate_pct":{"type":"number","minimum":0,"maximum":100},"min_sample":{"type":"integer","minimum":1,"maximum":10000}},"required":["velocity_leads_per_hour","same_device_max_leads","no_witty_reply_hours","off_hours_start","off_hours_end","off_hours_burst","junk_rate_pct","min_sample"],"additionalProperties":false}'::jsonb, '{"velocity_leads_per_hour":30,"same_device_max_leads":3,"no_witty_reply_hours":48,"off_hours_start":"00:30","off_hours_end":"06:00","off_hours_burst":5,"junk_rate_pct":40,"min_sample":10}'::jsonb, 'settings.write', null),
  ('attribution.links', 'attribution', 'Links and Witty', 'Witty''s WhatsApp number for deep links, the pre-filled message and UTM defaults.', '{"type":"object","properties":{"witty_whatsapp_number":{"type":"string","pattern":"^[1-9]\\d{9,14}$"},"deep_link_template":{"type":"string","minLength":10,"maxLength":500},"issue_witty_access_codes":{"type":"boolean"},"utm_source":{"type":"string","minLength":1,"maxLength":60},"short_link_base":{"type":"string","maxLength":200},"website_base_url":{"type":"string","maxLength":200,"pattern":"^https:\\/\\/[^\\s/]+\\.[^\\s]+$"}},"required":["witty_whatsapp_number","deep_link_template","issue_witty_access_codes","utm_source","short_link_base","website_base_url"],"additionalProperties":false}'::jsonb, '{"witty_whatsapp_number":"919643977407","deep_link_template":"Hi Eduwit! I saw {creator_name}''s post about {programme}. My access code is {access_code} (ref {code})","issue_witty_access_codes":true,"utm_source":"influencer","short_link_base":"https://creators.eduwit.in/r/","website_base_url":"https://eduwit.in"}'::jsonb, 'settings.write', null),
  ('lead_visibility.creator', 'lead_visibility', 'What creators see', 'Fields shown to creators on their leads. Phone and email are always masked and cannot be unmasked here.', '{"type":"object","properties":{"fields":{"maxItems":26,"type":"array","items":{"type":"string","enum":["display_name","city","state","country","preferred_language","enquirer_relation","interested_course","interested_specialization","field_of_interest","interested_university","university_preference","program_level","programme_segment","study_mode_preference","highest_qualification","current_study","enrollment_timeline","eligibility_status","admission_readiness","lead_status","experience_band","first_touch_at","applied_at","enrolled_program","enrolled_university","enrollment_date"]}},"name_format":{"type":"string","enum":["first_initial","first_name","full","hidden"]},"public_mail_domains":{"maxItems":50,"type":"array","items":{"type":"string","pattern":"^[a-z0-9.-]+\\.[a-z]{2,}$"}}},"required":["fields","name_format","public_mail_domains"],"additionalProperties":false}'::jsonb, '{"fields":["display_name","city","state","country","preferred_language","enquirer_relation","interested_course","interested_specialization","field_of_interest","interested_university","university_preference","program_level","programme_segment","study_mode_preference","highest_qualification","current_study","enrollment_timeline","eligibility_status","admission_readiness","lead_status","experience_band","first_touch_at","applied_at","enrolled_program","enrolled_university","enrollment_date"],"name_format":"first_initial","public_mail_domains":["gmail.com","yahoo.com","yahoo.co.in","outlook.com","hotmail.com","live.com","icloud.com","rediffmail.com","proton.me"]}'::jsonb, 'settings.write', null),
  ('compensation.defaults', 'compensation', 'Compensation defaults', 'Rounding, hold and refund windows, penalty caps and the default commission base.', '{"type":"object","properties":{"rounding":{"type":"string","const":"bankers"},"hold_days":{"type":"integer","minimum":0,"maximum":365},"refund_window_days":{"type":"integer","minimum":0,"maximum":365},"penalty_cap_pct":{"type":"number","minimum":0,"maximum":100},"commission_base_default":{"type":"string","enum":["gross_incl_gst","net_of_gst"]},"confirm_partial_receipts":{"type":"boolean"},"eduwit_commission_overdue_days":{"type":"integer","minimum":0,"maximum":365},"eduwit_commission_gst_pct":{"type":"number","minimum":0,"maximum":100}},"required":["rounding","hold_days","refund_window_days","penalty_cap_pct","commission_base_default","confirm_partial_receipts","eduwit_commission_overdue_days","eduwit_commission_gst_pct"],"additionalProperties":false}'::jsonb, '{"rounding":"bankers","hold_days":30,"refund_window_days":30,"penalty_cap_pct":20,"commission_base_default":"net_of_gst","confirm_partial_receipts":false,"eduwit_commission_overdue_days":60,"eduwit_commission_gst_pct":18}'::jsonb, 'settings.write', null),
  ('contracts.signing', 'contracts', 'Signing and reminders', 'OTP channels and limits, negotiation reminders, expiry reminders and the legal-review gate.', '{"type":"object","properties":{"otp_channels":{"minItems":1,"maxItems":2,"type":"array","items":{"type":"string","enum":["email","whatsapp"]}},"otp_expiry_minutes":{"type":"integer","minimum":2,"maximum":30},"otp_max_attempts":{"type":"integer","minimum":1,"maximum":10},"otp_resend_cooldown_seconds":{"type":"integer","minimum":15,"maximum":600},"negotiation_deadline_days":{"type":"integer","minimum":1,"maximum":60},"negotiation_reminder_days":{"maxItems":5,"type":"array","items":{"type":"integer","minimum":1,"maximum":60}},"expiry_reminder_days":{"maxItems":5,"type":"array","items":{"type":"integer","minimum":1,"maximum":120}},"legal_review_gate":{"type":"boolean"}},"required":["otp_channels","otp_expiry_minutes","otp_max_attempts","otp_resend_cooldown_seconds","negotiation_deadline_days","negotiation_reminder_days","expiry_reminder_days","legal_review_gate"],"additionalProperties":false}'::jsonb, '{"otp_channels":["email"],"otp_expiry_minutes":10,"otp_max_attempts":5,"otp_resend_cooldown_seconds":60,"negotiation_deadline_days":7,"negotiation_reminder_days":[2,5],"expiry_reminder_days":[30,15,7],"legal_review_gate":true}'::jsonb, 'settings.write', 'Stamp duty and enforceability depend on the state and contract type. Confirm with counsel before relying on OTP click-sign.'),
  ('content.review', 'content', 'Content review', 'Revision limits, disclosure rules per platform and metric checkpoints.', '{"type":"object","properties":{"default_revision_limit":{"type":"integer","minimum":0,"maximum":20},"metric_checkpoints_hours":{"minItems":1,"maxItems":6,"type":"array","items":{"type":"integer","minimum":1,"maximum":2160}},"disclosure_terms":{"minItems":1,"maxItems":20,"type":"array","items":{"type":"string","minLength":2,"maxLength":60}},"disclosure_required_platforms":{"type":"array","items":{"type":"string","enum":["instagram","youtube","facebook","linkedin","x","telegram","moj_josh","other"]}}},"required":["default_revision_limit","metric_checkpoints_hours","disclosure_terms","disclosure_required_platforms"],"additionalProperties":false}'::jsonb, '{"default_revision_limit":2,"metric_checkpoints_hours":[24,168,720],"disclosure_terms":["#ad","#collab","#sponsored","paid partnership"],"disclosure_required_platforms":["instagram","youtube","facebook","linkedin","x","telegram","moj_josh","other"]}'::jsonb, 'settings.write', null),
  ('content.schedule', 'content', 'Due dates and reminders', 'Reminders before deliverable due dates, when overdue work is escalated to the deal owner, and how long after the post metrics are due.', '{"type":"object","properties":{"due_reminder_days":{"maxItems":5,"type":"array","items":{"type":"integer","minimum":1,"maximum":30}},"overdue_escalation_days":{"type":"integer","minimum":1,"maximum":30},"metrics_grace_hours":{"type":"integer","minimum":0,"maximum":336}},"required":["due_reminder_days","overdue_escalation_days","metrics_grace_hours"],"additionalProperties":false}'::jsonb, '{"due_reminder_days":[2],"overdue_escalation_days":2,"metrics_grace_hours":48}'::jsonb, 'settings.write', null),
  ('content.uploads', 'content', 'Upload limits', 'Maximum sizes per file kind. Allowed types are fixed by the app.', '{"type":"object","properties":{"max_video_mb":{"type":"integer","minimum":10,"maximum":10240},"max_image_mb":{"type":"integer","minimum":1,"maximum":100},"max_document_mb":{"type":"integer","minimum":1,"maximum":100}},"required":["max_video_mb","max_image_mb","max_document_mb"],"additionalProperties":false}'::jsonb, '{"max_video_mb":2048,"max_image_mb":20,"max_document_mb":25}'::jsonb, 'settings.write', null),
  ('finance.payouts', 'finance', 'Payouts', 'Payout cycle, approvals, KYC rule and the bank bulk-upload format.', '{"type":"object","properties":{"cycle":{"type":"string","enum":["weekly","fortnightly","monthly"]},"payout_day_of_month":{"type":"integer","minimum":1,"maximum":28},"two_person_approval":{"type":"boolean"},"kyc_required_for_payout":{"type":"boolean"},"hold_until_tax_confirmed":{"type":"boolean"},"bank_export":{"type":"object","properties":{"delimiter":{"type":"string","enum":[",",";","|","\t"]},"header":{"type":"boolean"},"columns":{"minItems":3,"maxItems":12,"type":"array","items":{"type":"string","enum":["beneficiary_name","account_number","ifsc","amount_inr","narration","payout_ref","email","creator_code"]}}},"required":["delimiter","header","columns"],"additionalProperties":false}},"required":["cycle","payout_day_of_month","two_person_approval","kyc_required_for_payout","hold_until_tax_confirmed","bank_export"],"additionalProperties":false}'::jsonb, '{"cycle":"monthly","payout_day_of_month":10,"two_person_approval":true,"kyc_required_for_payout":true,"hold_until_tax_confirmed":false,"bank_export":{"delimiter":",","header":true,"columns":["beneficiary_name","account_number","ifsc","amount_inr","narration","payout_ref"]}}'::jsonb, 'tax.manage', null),
  ('finance.gst', 'finance', 'GST', 'GST on creator payouts when the creator''s GSTIN is verified.', '{"type":"object","properties":{"rate_pct":{"type":"number","minimum":0,"maximum":100},"require_invoice_for_registered":{"type":"boolean"},"sac_code":{"type":"string","pattern":"^(\\d{6})?$"}},"required":["rate_pct","require_invoice_for_registered","sac_code"],"additionalProperties":false}'::jsonb, '{"rate_pct":18,"require_invoice_for_registered":true,"sac_code":"998361"}'::jsonb, 'tax.manage', 'GST rate and SAC code: confirm with your CA.'),
  ('creators.lifecycle', 'creators', 'Creator lifecycle', 'Dormancy flag, onboarding requirements and self sign-up approval.', '{"type":"object","properties":{"dormant_after_days":{"type":"integer","minimum":7,"maximum":365},"auto_approve_signups":{"type":"boolean"},"auto_approve_min_followers":{"type":"integer","minimum":0,"maximum":100000000},"course_pass_pct":{"type":"integer","minimum":50,"maximum":100},"require_kyc_to_submit":{"type":"boolean"}},"required":["dormant_after_days","auto_approve_signups","auto_approve_min_followers","course_pass_pct","require_kyc_to_submit"],"additionalProperties":false}'::jsonb, '{"dormant_after_days":45,"auto_approve_signups":false,"auto_approve_min_followers":10000,"course_pass_pct":80,"require_kyc_to_submit":true}'::jsonb, 'settings.write', null),
  ('scorecard.weights', 'scorecard', 'Score weights', 'Weights of the composite creator score (they need not sum to 1; they are normalised).', '{"type":"object","properties":{"delivery":{"type":"number","minimum":0,"maximum":1},"content":{"type":"number","minimum":0,"maximum":1},"lead_quality":{"type":"number","minimum":0,"maximum":1},"economics":{"type":"number","minimum":0,"maximum":1},"compliance":{"type":"number","minimum":0,"maximum":1}},"required":["delivery","content","lead_quality","economics","compliance"],"additionalProperties":false}'::jsonb, '{"delivery":0.25,"content":0.2,"lead_quality":0.25,"economics":0.2,"compliance":0.1}'::jsonb, 'tier.manage', null),
  ('notifications.delivery', 'notifications', 'Delivery', 'Quiet hours (IST) for WhatsApp and digests. Mandatory events still arrive in-app and by email.', '{"type":"object","properties":{"quiet_hours_start":{"type":"string","pattern":"^([01]\\d|2[0-3]):[0-5]\\d$"},"quiet_hours_end":{"type":"string","pattern":"^([01]\\d|2[0-3]):[0-5]\\d$"},"creator_digest":{"type":"string","enum":["off","daily","weekly"]},"staff_digest":{"type":"string","enum":["off","daily","weekly"]},"digest_hour_ist":{"type":"integer","minimum":0,"maximum":23}},"required":["quiet_hours_start","quiet_hours_end","creator_digest","staff_digest","digest_hour_ist"],"additionalProperties":false}'::jsonb, '{"quiet_hours_start":"21:00","quiet_hours_end":"09:00","creator_digest":"weekly","staff_digest":"daily","digest_hour_ist":9}'::jsonb, 'settings.write', null),
  ('security.sessions', 'security', 'Sessions', 'Idle sign-out and trusted devices for staff.', '{"type":"object","properties":{"idle_timeout_hours":{"type":"integer","minimum":1,"maximum":72},"trusted_device_days":{"type":"integer","minimum":0,"maximum":90}},"required":["idle_timeout_hours","trusted_device_days"],"additionalProperties":false}'::jsonb, '{"idle_timeout_hours":12,"trusted_device_days":30}'::jsonb, 'settings.write', null),
  ('retention.privacy', 'retention', 'Retention', 'How long records are kept. Financial and contract records: at least 8 years.', '{"type":"object","properties":{"financial_records_years":{"type":"integer","minimum":8,"maximum":20},"audit_log_years":{"type":"integer","minimum":1,"maximum":20},"click_anonymise_days":{"type":"integer","minimum":1,"maximum":730},"sign_in_log_days":{"type":"integer","minimum":30,"maximum":3650}},"required":["financial_records_years","audit_log_years","click_anonymise_days","sign_in_log_days"],"additionalProperties":false}'::jsonb, '{"financial_records_years":8,"audit_log_years":8,"click_anonymise_days":90,"sign_in_log_days":365}'::jsonb, 'settings.write', null)
